const translatedAttributes = ['placeholder', 'title', 'aria-label', 'alt'] as const
const skippedTags = new Set(['SCRIPT', 'STYLE', 'CODE', 'PRE', 'TEXTAREA'])

function normalizePunctuation(value: string) {
  return value
    .split('，').join(', ')
    .split('。').join('.')
    .split('；').join('; ')
    .split('：').join(': ')
    .split('（').join('(')
    .split('）').join(')')
    .split('“').join('«')
    .split('”').join('»')
    .replace(/\s+,\s+/g, ', ')
    .replace(/\s+;\s+/g, '; ')
}

export function translateRussianUiText(value: string): string {
  if (!value || !hanPattern.test(value)) return value
  const match = value.match(/^(\s*)([\s\S]*?)(\s*)$/)
  const lead = match?.[1] ?? ''
  const body = match?.[2] ?? value
  const tail = match?.[3] ?? ''

  let translated = exactTranslations.get(body) ?? body
  if (translated === body) {
    for (const [pattern, replacement] of dynamicTranslations) {
      if (pattern.test(translated)) {
        translated = translated.replace(pattern, replacement)
        break
      }
    }
  }
  if (hanPattern.test(translated)) {
    for (const [source, target] of substringTranslations) {
      if (translated.includes(source)) translated = translated.split(source).join(target)
    }
  }
  if (translated !== body) translated = normalizePunctuation(translated)
  // Common Chinese counters left around dynamic numeric values.
  translated = translated
    .replace(/(\d[\d\s.,]*)\s*个(?=\s|$|[()])/g, '$1')
    .replace(/(\d[\d\s.,]*)\s*(?:条|项)(?=\s|$|[()])/g, '$1')
  return `${lead}${translated}${tail}`
}

function shouldSkip(element: Element | null) {
  if (!element) return false
  if (skippedTags.has(element.tagName)) return true
  return Boolean(element.closest('script,style,code,pre,textarea,[contenteditable="true"]'))
}

function translateTextNode(node: Text) {
  if (!node.data || !hanPattern.test(node.data) || shouldSkip(node.parentElement)) return
  const translated = translateRussianUiText(node.data)
  if (translated !== node.data) node.data = translated
}

function translateElement(element: Element) {
  if (shouldSkip(element)) return
  for (const name of translatedAttributes) {
    const value = element.getAttribute(name)
    if (!value || !hanPattern.test(value)) continue
    const translated = translateRussianUiText(value)
    if (translated !== value) element.setAttribute(name, translated)
  }
}

function translateTree(root: Node) {
  if (root.nodeType === Node.TEXT_NODE) {
    translateTextNode(root as Text)
    return
  }
  if (root.nodeType !== Node.ELEMENT_NODE && root.nodeType !== Node.DOCUMENT_NODE && root.nodeType !== Node.DOCUMENT_FRAGMENT_NODE) return
  if (root instanceof Element) translateElement(root)
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT)
  let node: Node | null = walker.nextNode()
  while (node) {
    if (node.nodeType === Node.TEXT_NODE) translateTextNode(node as Text)
    else if (node instanceof Element) translateElement(node)
    node = walker.nextNode()
  }
}

let observer: MutationObserver | null = null
export function installRussianRuntimeLocalization() {
  document.documentElement.lang = 'ru-RU'
  translateTree(document.documentElement)
  if (observer) return
  observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      if (mutation.type === 'characterData') translateTree(mutation.target)
      else if (mutation.type === 'attributes' && mutation.target instanceof Element) translateElement(mutation.target)
      else for (const node of mutation.addedNodes) translateTree(node)
    }
  })
  observer.observe(document.documentElement, {
    subtree: true,
    childList: true,
    characterData: true,
    attributes: true,
    attributeFilter: [...translatedAttributes],
  })
}

